// Deterministic job dependency planner.
//
// Exports a synchronous planJobs(spec) plus a small CLI:
//
//   node job-plan.js SPECFILE
//
// The CLI reads a UTF-8 JSON job spec, prints the plan as JSON followed by a
// newline on stdout, and exits 0. Invalid arguments, unreadable input,
// invalid JSON, or invalid graphs write a message to stderr, write nothing
// to stdout, and exit 2. Importing the module does not run the CLI.
//
// Node.js builtins only.

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import process from 'node:process';

function fail(message) {
  throw new Error(message);
}

// JavaScript `<`/`>` code-unit string ordering (not locale collation).
function cmpStr(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

// Min-heap of job ids under cmpStr.
class MinHeap {
  constructor() {
    this.items = [];
  }

  get size() {
    return this.items.length;
  }

  push(value) {
    const items = this.items;
    items.push(value);
    let index = items.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (cmpStr(items[parent], items[index]) <= 0) break;
      const tmp = items[parent];
      items[parent] = items[index];
      items[index] = tmp;
      index = parent;
    }
  }

  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let index = 0;
      for (;;) {
        const left = index * 2 + 1;
        const right = left + 1;
        let smallest = index;
        if (left < items.length && cmpStr(items[left], items[smallest]) < 0) smallest = left;
        if (right < items.length && cmpStr(items[right], items[smallest]) < 0) smallest = right;
        if (smallest === index) break;
        const tmp = items[smallest];
        items[smallest] = items[index];
        items[index] = tmp;
        index = smallest;
      }
    }
    return top;
  }
}

/**
 * Plan a job spec deterministically.
 *
 * @param {Array<{id: string, deps: string[], state: string}>} spec
 * @returns {{order: string[], ready: string[], blocked: Array<{id: string, causes: string[]}>}}
 */
export function planJobs(spec) {
  if (!Array.isArray(spec)) fail('spec must be an array of job objects');

  // Map keeps "__proto__" and "constructor" as ordinary keys. The input is
  // only read, never mutated, and unknown fields are ignored.
  const jobs = new Map(); // id -> { id, deps, state }
  for (let i = 0; i < spec.length; i += 1) {
    const entry = spec[i];
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
      fail(`job at index ${i} must be an object`);
    }
    const id = entry.id;
    if (typeof id !== 'string' || id.length === 0) {
      fail(`job at index ${i} must have a nonempty string id`);
    }
    const deps = entry.deps;
    if (!Array.isArray(deps)) {
      fail(`job ${JSON.stringify(id)} must have a deps array`);
    }
    const depSeen = new Set();
    for (const dep of deps) {
      if (typeof dep !== 'string' || dep.length === 0) {
        fail(`job ${JSON.stringify(id)} must have nonempty string dependencies`);
      }
      if (depSeen.has(dep)) {
        fail(`job ${JSON.stringify(id)} has a duplicate dependency ${JSON.stringify(dep)}`);
      }
      depSeen.add(dep);
    }
    const state = entry.state;
    if (state !== 'pending' && state !== 'succeeded' && state !== 'failed') {
      fail(`job ${JSON.stringify(id)} must have state "pending", "succeeded", or "failed"`);
    }
    if (jobs.has(id)) {
      fail(`duplicate job id ${JSON.stringify(id)}`);
    }
    jobs.set(id, { id, deps, state });
  }

  for (const { id, deps } of jobs.values()) {
    for (const dep of deps) {
      if (!jobs.has(dep)) {
        fail(`job ${JSON.stringify(id)} references unknown id ${JSON.stringify(dep)}`);
      }
    }
  }

  // Kahn's algorithm over the ENTIRE graph: repeatedly remove the lexically
  // smallest currently zero-indegree id, updating its dependents first.
  const children = new Map(); // id -> ids that directly depend on it
  const indegree = new Map(); // id -> dependency count
  for (const { id, deps } of jobs.values()) {
    indegree.set(id, deps.length);
    for (const dep of deps) {
      const list = children.get(dep);
      if (list === undefined) children.set(dep, [id]);
      else list.push(id);
    }
  }

  const heap = new MinHeap();
  for (const [id, degree] of indegree) {
    if (degree === 0) heap.push(id);
  }

  const fullOrder = [];
  while (heap.size > 0) {
    const id = heap.pop();
    fullOrder.push(id);
    const list = children.get(id);
    if (list === undefined) continue;
    for (const child of list) {
      const remaining = indegree.get(child) - 1;
      indegree.set(child, remaining);
      if (remaining === 0) heap.push(child);
    }
  }
  if (fullOrder.length !== jobs.size) {
    fail('dependency graph contains a cycle');
  }

  // Every failed ancestor (direct or transitive) of each id. Paths go through
  // any intermediate state: succeeded or failed intermediates do not erase
  // ancestry. fullOrder lists each dependency before its dependents.
  const failedAncestors = new Map(); // id -> Set of failed ancestor ids
  for (const id of fullOrder) {
    const { deps } = jobs.get(id);
    const causes = new Set();
    for (const dep of deps) {
      if (jobs.get(dep).state === 'failed') causes.add(dep);
      for (const ancestor of failedAncestors.get(dep)) causes.add(ancestor);
    }
    failedAncestors.set(id, causes);
  }

  const order = [];
  const ready = [];
  const blocked = [];
  for (const id of fullOrder) {
    const { deps, state } = jobs.get(id);
    if (state !== 'pending') continue;
    const causes = failedAncestors.get(id);
    if (causes.size > 0) {
      blocked.push({ id, causes: [...causes].sort(cmpStr) });
      continue;
    }
    order.push(id);
    let allSucceeded = true;
    for (const dep of deps) {
      if (jobs.get(dep).state !== 'succeeded') {
        allSucceeded = false;
        break;
      }
    }
    if (allSucceeded) ready.push(id);
  }

  ready.sort(cmpStr);
  blocked.sort((a, b) => cmpStr(a.id, b.id));
  return { order, ready, blocked };
}

function runCli() {
  const args = process.argv.slice(2);
  try {
    if (args.length !== 1) {
      fail('usage: node job-plan.js SPECFILE');
    }
    const raw = readFileSync(args[0], 'utf8');
    const spec = JSON.parse(raw);
    const plan = planJobs(spec);
    process.stdout.write(`${JSON.stringify(plan)}\n`);
  } catch (err) {
    process.stderr.write(`${err instanceof Error ? err.message : String(err)}\n`);
    process.exitCode = 2;
  }
}

const entryPoint = process.argv[1];
if (entryPoint !== undefined && entryPoint !== '' && import.meta.url === pathToFileURL(entryPoint).href) {
  runCli();
}

import test, { after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('malformed specs and fields throw', () => {
  assert.throws(() => planJobs('nope'));
  assert.throws(() => planJobs(null));
  assert.throws(() => planJobs({}));
  assert.throws(() => planJobs([1]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs([[]]));
  assert.throws(() => planJobs([{ id: 1, deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: '', deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: 'b', state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [1], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['a', 'a'], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'done' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'Pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'pending' }, { id: 'a', deps: [], state: 'succeeded' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['missing'], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['a'], state: 'pending' }]));
  // Cycles are checked over the entire graph, including completed/failed jobs.
  assert.throws(() => planJobs([{ id: 'a', deps: ['b'], state: 'succeeded' }, { id: 'b', deps: ['a'], state: 'failed' }]));
  assert.throws(() => planJobs([
    { id: 'a', deps: ['b'], state: 'failed' },
    { id: 'b', deps: ['c'], state: 'succeeded' },
    { id: 'c', deps: ['a'], state: 'pending' },
  ]));
});

test('__proto__ and constructor are ordinary ids', () => {
  const plan = planJobs([
    { id: '__proto__', deps: ['constructor'], state: 'pending' },
    { id: 'constructor', deps: [], state: 'pending' },
  ]);
  assert.deepEqual(plan, { order: ['constructor', '__proto__'], ready: ['constructor'], blocked: [] });
  assert.equal(typeof Object.prototype.toString, 'function');
});

test('failed ancestry is transitive through any intermediate state', () => {
  const plan = planJobs([
    job('f1', [], 'failed'),
    job('f2', [], 'failed'),
    job('mid', ['f1', 'f2'], 'failed'),
    job('end', ['mid']),
    job('ok', ['f1'], 'succeeded'),
    job('after', ['ok']),
  ]);
  assert.deepEqual(plan, {
    order: [],
    ready: [],
    blocked: [
      { id: 'after', causes: ['f1'] },
      { id: 'end', causes: ['f1', 'f2'] },
    ],
  });
});

test('ready is id-sorted and requires every direct dep to be succeeded', () => {
  // Full topological order is [b, z, a]; ready must be id-sorted [a, b].
  const plan = planJobs([
    job('a', ['z']),
    job('b'),
    job('z', [], 'succeeded'),
  ]);
  assert.deepEqual(plan, { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
});

test('succeeded intermediate does not erase failed ancestry', () => {
  const plan = planJobs([
    job('f', [], 'failed'),
    job('s', ['f'], 'succeeded'),
    job('p', ['s']),
  ]);
  assert.deepEqual(plan, { order: [], ready: [], blocked: [{ id: 'p', causes: ['f'] }] });
});

test('ordering considers completed jobs, not just the pending subgraph', () => {
  // Pending-only topological sort would put "a" first; the whole-graph order
  // processes succeeded "c" before unlocking "a".
  const plan = planJobs([
    job('a', ['c']),
    job('b'),
    job('c', [], 'succeeded'),
  ]);
  assert.deepEqual(plan, { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
});

test('deterministic Kahn ordering over the whole graph', () => {
  const plan = planJobs([
    job('d', ['b', 'c']),
    job('b', ['a']),
    job('c', ['a']),
    job('a'),
  ]);
  assert.deepEqual(plan, { order: ['a', 'b', 'c', 'd'], ready: ['a'], blocked: [] });
});

test('does not mutate the input and ignores unknown fields', () => {
  const rocket = '\u{1F680}';
  const spec = [
    { id: ' a ', deps: [rocket], state: 'pending', meta: { whatever: [1, 2, { deep: true }] } },
    { id: rocket, deps: [], state: 'pending' },
  ];
  const snapshot = JSON.parse(JSON.stringify(spec));
  const plan = planJobs(spec);
  assert.deepEqual(spec, snapshot);
  assert.deepEqual(plan, { order: [rocket, ' a '], ready: [rocket], blocked: [] });
});

test('empty spec', () => {
  assert.deepEqual(planJobs([]), { order: [], ready: [], blocked: [] });
});

// ---------------------------------------------------------------------------
// CLI behaviour
// ---------------------------------------------------------------------------

const scriptPath = fileURLToPath(new URL('../job-plan.js', import.meta.url));
const scriptUrl = pathToFileURL(scriptPath).href;
const runCli = (args) => spawnSync(process.execPath, [scriptPath, ...args], { encoding: 'utf8' });
const tmp = mkdtempSync(join(tmpdir(), 'job-plan-'));
after(() => rmSync(tmp, { recursive: true, force: true }));

test('cli prints the plan as JSON plus newline and exits 0', () => {
  const file = join(tmp, 'ok.json');
  writeFileSync(file, JSON.stringify([job('b'), job('a', ['b'])]));
  const res = runCli([file]);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.equal(res.stdout, `${JSON.stringify({ order: ['b', 'a'], ready: ['b'], blocked: [] })}\n`);
});

test('cli errors exit 2 with nonempty stderr and no stdout', () => {
  const cases = [
    [join(tmp, 'does-not-exist.json')],
    [],
    ['a', 'b'],
  ];
  for (const args of cases) {
    const res = runCli(args);
    assert.equal(res.status, 2, `args ${JSON.stringify(args)}`);
    assert.equal(res.stdout, '');
    assert.ok(res.stderr.length > 0);
  }

  const badJsonFile = join(tmp, 'bad.json');
  writeFileSync(badJsonFile, '{not json');
  const badJson = runCli([badJsonFile]);
  assert.equal(badJson.status, 2);
  assert.equal(badJson.stdout, '');
  assert.ok(badJson.stderr.length > 0);

  const notArrayFile = join(tmp, 'not-array.json');
  writeFileSync(notArrayFile, JSON.stringify({ id: 'a', deps: [], state: 'pending' }));
  const notArray = runCli([notArrayFile]);
  assert.equal(notArray.status, 2);
  assert.equal(notArray.stdout, '');

  const cycleFile = join(tmp, 'cycle.json');
  writeFileSync(cycleFile, JSON.stringify([job('a', ['b']), job('b', ['a'])]));
  const cycle = runCli([cycleFile]);
  assert.equal(cycle.status, 2);
  assert.equal(cycle.stdout, '');
  assert.ok(cycle.stderr.length > 0);
});

test('importing the module does not run the CLI', () => {
  const res = spawnSync(
    process.execPath,
    ['-e', `import(${JSON.stringify(scriptUrl)}).catch((e) => { console.error(e); process.exit(3); });`],
    { encoding: 'utf8' },
  );
  assert.equal(res.status, 0);
  assert.equal(res.stdout, '');
  assert.equal(res.stderr, '');
});

