// Deterministic job dependency planner.
//
// Exports a synchronous planJobs(spec) plus a small CLI:
//
//   node job-plan.js SPECFILE
//
// The CLI reads a UTF-8 JSON job spec, prints the plan as JSON followed by a
// newline on stdout, and exits 0. Invalid arguments, unreadable input,
// invalid JSON, or invalid graphs write a message to stderr, write nothing
// to stdout, and exit 2. Importing the module does not run the CLI.
//
// Node.js builtins only.

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import process from 'node:process';

function fail(message) {
  throw new Error(message);
}

// JavaScript `<`/`>` code-unit string ordering (not locale collation).
function cmpStr(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

// Min-heap of job ids under cmpStr.
class MinHeap {
  constructor() {
    this.items = [];
  }

  get size() {
    return this.items.length;
  }

  push(value) {
    const items = this.items;
    items.push(value);
    let index = items.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (cmpStr(items[parent], items[index]) <= 0) break;
      const tmp = items[parent];
      items[parent] = items[index];
      items[index] = tmp;
      index = parent;
    }
  }

  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let index = 0;
      for (;;) {
        const left = index * 2 + 1;
        const right = left + 1;
        let smallest = index;
        if (left < items.length && cmpStr(items[left], items[smallest]) < 0) smallest = left;
        if (right < items.length && cmpStr(items[right], items[smallest]) < 0) smallest = right;
        if (smallest === index) break;
        const tmp = items[smallest];
        items[smallest] = items[index];
        items[index] = tmp;
        index = smallest;
      }
    }
    return top;
  }
}

/**
 * Plan a job spec deterministically.
 *
 * @param {Array<{id: string, deps: string[], state: string}>} spec
 * @returns {{order: string[], ready: string[], blocked: Array<{id: string, causes: string[]}>}}
 */
export function planJobs(spec) {
  if (!Array.isArray(spec)) fail('spec must be an array of job objects');

  // Map keeps "__proto__" and "constructor" as ordinary keys. The input is
  // only read, never mutated, and unknown fields are ignored.
  const jobs = new Map(); // id -> { id, deps, state }
  for (let i = 0; i < spec.length; i += 1) {
    const entry = spec[i];
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
      fail(`job at index ${i} must be an object`);
    }
    const id = entry.id;
    if (typeof id !== 'string' || id.length === 0) {
      fail(`job at index ${i} must have a nonempty string id`);
    }
    const deps = entry.deps;
    if (!Array.isArray(deps)) {
      fail(`job ${JSON.stringify(id)} must have a deps array`);
    }
    const depSeen = new Set();
    for (const dep of deps) {
      if (typeof dep !== 'string' || dep.length === 0) {
        fail(`job ${JSON.stringify(id)} must have nonempty string dependencies`);
      }
      if (depSeen.has(dep)) {
        fail(`job ${JSON.stringify(id)} has a duplicate dependency ${JSON.stringify(dep)}`);
      }
      depSeen.add(dep);
    }
    const state = entry.state;
    if (state !== 'pending' && state !== 'succeeded' && state !== 'failed') {
      fail(`job ${JSON.stringify(id)} must have state "pending", "succeeded", or "failed"`);
    }
    if (jobs.has(id)) {
      fail(`duplicate job id ${JSON.stringify(id)}`);
    }
    jobs.set(id, { id, deps, state });
  }

  for (const { id, deps } of jobs.values()) {
    for (const dep of deps) {
      if (!jobs.has(dep)) {
        fail(`job ${JSON.stringify(id)} references unknown id ${JSON.stringify(dep)}`);
      }
    }
  }

  // Kahn's algorithm over the ENTIRE graph: repeatedly remove the lexically
  // smallest currently zero-indegree id, updating its dependents first.
  const children = new Map(); // id -> ids that directly depend on it
  const indegree = new Map(); // id -> dependency count
  for (const { id, deps } of jobs.values()) {
    indegree.set(id, deps.length);
    for (const dep of deps) {
      const list = children.get(dep);
      if (list === undefined) children.set(dep, [id]);
      else list.push(id);
    }
  }

  const heap = new MinHeap();
  for (const [id, degree] of indegree) {
    if (degree === 0) heap.push(id);
  }

  const fullOrder = [];
  while (heap.size > 0) {
    const id = heap.pop();
    fullOrder.push(id);
    const list = children.get(id);
    if (list === undefined) continue;
    for (const child of list) {
      const remaining = indegree.get(child) - 1;
      indegree.set(child, remaining);
      if (remaining === 0) heap.push(child);
    }
  }
  if (fullOrder.length !== jobs.size) {
    fail('dependency graph contains a cycle');
  }

  // Every failed ancestor (direct or transitive) of each id. Paths go through
  // any intermediate state: succeeded or failed intermediates do not erase
  // ancestry. fullOrder lists each dependency before its dependents.
  const failedAncestors = new Map(); // id -> Set of failed ancestor ids
  for (const id of fullOrder) {
    const { deps } = jobs.get(id);
    const causes = new Set();
    for (const dep of deps) {
      if (jobs.get(dep).state === 'failed') causes.add(dep);
      for (const ancestor of failedAncestors.get(dep)) causes.add(ancestor);
    }
    failedAncestors.set(id, causes);
  }

  const order = [];
  const ready = [];
  const blocked = [];
  for (const id of fullOrder) {
    const { deps, state } = jobs.get(id);
    if (state !== 'pending') continue;
    const causes = failedAncestors.get(id);
    if (causes.size > 0) {
      blocked.push({ id, causes: [...causes].sort(cmpStr) });
      continue;
    }
    order.push(id);
    let allSucceeded = true;
    for (const dep of deps) {
      if (jobs.get(dep).state !== 'succeeded') {
        allSucceeded = false;
        break;
      }
    }
    if (allSucceeded) ready.push(id);
  }

  ready.sort(cmpStr);
  blocked.sort((a, b) => cmpStr(a.id, b.id));
  return { order, ready, blocked };
}

function runCli() {
  const args = process.argv.slice(2);
  try {
    if (args.length !== 1) {
      fail('usage: node job-plan.js SPECFILE');
    }
    const raw = readFileSync(args[0], 'utf8');
    const spec = JSON.parse(raw);
    const plan = planJobs(spec);
    process.stdout.write(`${JSON.stringify(plan)}\n`);
  } catch (err) {
    process.stderr.write(`${err instanceof Error ? err.message : String(err)}\n`);
    process.exitCode = 2;
  }
}

const entryPoint = process.argv[1];
if (entryPoint !== undefined && entryPoint !== '' && import.meta.url === pathToFileURL(entryPoint).href) {
  runCli();
}

