import test, { after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('malformed specs and fields throw', () => {
  assert.throws(() => planJobs('nope'));
  assert.throws(() => planJobs(null));
  assert.throws(() => planJobs({}));
  assert.throws(() => planJobs([1]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs([[]]));
  assert.throws(() => planJobs([{ id: 1, deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: '', deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: 'b', state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [1], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['a', 'a'], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'done' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'Pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'pending' }, { id: 'a', deps: [], state: 'succeeded' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['missing'], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: ['a'], state: 'pending' }]));
  // Cycles are checked over the entire graph, including completed/failed jobs.
  assert.throws(() => planJobs([{ id: 'a', deps: ['b'], state: 'succeeded' }, { id: 'b', deps: ['a'], state: 'failed' }]));
  assert.throws(() => planJobs([
    { id: 'a', deps: ['b'], state: 'failed' },
    { id: 'b', deps: ['c'], state: 'succeeded' },
    { id: 'c', deps: ['a'], state: 'pending' },
  ]));
});

test('__proto__ and constructor are ordinary ids', () => {
  const plan = planJobs([
    { id: '__proto__', deps: ['constructor'], state: 'pending' },
    { id: 'constructor', deps: [], state: 'pending' },
  ]);
  assert.deepEqual(plan, { order: ['constructor', '__proto__'], ready: ['constructor'], blocked: [] });
  assert.equal(typeof Object.prototype.toString, 'function');
});

test('failed ancestry is transitive through any intermediate state', () => {
  const plan = planJobs([
    job('f1', [], 'failed'),
    job('f2', [], 'failed'),
    job('mid', ['f1', 'f2'], 'failed'),
    job('end', ['mid']),
    job('ok', ['f1'], 'succeeded'),
    job('after', ['ok']),
  ]);
  assert.deepEqual(plan, {
    order: [],
    ready: [],
    blocked: [
      { id: 'after', causes: ['f1'] },
      { id: 'end', causes: ['f1', 'f2', 'mid'] },
    ],
